L(16, "Sentado a ler, de pé à espera", "Hij zit te lezen.",
  ["Usar zitten/staan/liggen/lopen + te para ações em curso"],
  vocab=[X("v-zitten-te","zitten te …","estar (sentado) a …"), X("v-staan-te","staan te …","estar (de pé) a …"),
         X("v-liggen-te","liggen te …","estar (deitado) a …"), X("v-lopen-te","lopen te …","andar a …")],
  ex=[("Hij zit de hele dag te gamen.","Ele passa o dia sentado a jogar."),("Ze stond op de bus te wachten.","Ela estava à espera do autocarro."),("De baby ligt te slapen.","O bebé está a dormir."),("Hij loopt al weken te klagen.","Ele anda há semanas a queixar-se.")],
  review=["v-was-aan-het"],
  gram=[G("g-zitten-te","Zitten/staan/liggen/lopen + te","Para ações em curso, o neerlandês usa muitas vezes um verbo de posição + **te** + infinitivo: *Ik zit te eten* (estou a comer, sentado). **Lopen te** = «andar a» (algo que se repete, muitas vezes irritante). No perfeito usa-se o duplo infinitivo: *Ik heb zitten wachten.*",
    [("We zaten te praten.","Estávamos a conversar."),("Ik heb een uur staan wachten.","Estive uma hora à espera.")])],
  cefr=C, exs=[
    MA([("zitten te …","estar sentado a…"),("staan te …","estar de pé a…"),("liggen te …","estar deitado a…"),("lopen te …","andar a…")], "Posição.", ["v-zitten-te","v-staan-te","v-liggen-te","v-lopen-te"]),
    MC("O bebé está a dormir:", ["*De baby ligt te slapen.","De baby staat te slapen.|Os bebés dormem deitados.","De baby loopt te slapen.|Não."], "Posição natural.", ["v-liggen-te"]),
    MC("«Hij loopt altijd te zeuren» indica…", ["*ele anda sempre a queixar-se (irritante)","ele queixa-se a andar|Literal.","ele queixou-se uma vez|Não."], "lopen te.", ["v-lopen-te"]),
    TR("pt-nl","Ela estava à espera do autocarro.", ["Ze stond op de bus te wachten","Zij stond op de bus te wachten"], "staan te.", ["v-staan-te"]),
    TR("pt-nl","Estávamos a conversar.", ["We zaten te praten","Wij zaten te praten"], "zitten te.", ["v-zitten-te"]),
    FB("Ik heb een uur ___ wachten bij de dokter.", ["zitten"], "Duplo infinitivo.", ["v-zitten-te"], choices=["zitten","gezeten","zit"], tr="Estive uma hora à espera no médico."),
    FE(["Hij","zit","de","hele","dag","gamen."], 5, "te gamen", "Falta o te.", ["v-zitten-te"]),
    LI("Ik lag net te slapen toen de telefoon ging.", ["Ik lag net te slapen toen de telefoon ging"], "Estava mesmo a dormir quando o telefone tocou.", "liggen te.", ["v-liggen-te"]),
    WO("Ele está a ler.", ["Hij","zit","te","lezen"], "zit te + inf.", ["v-zitten-te"]),
  ], diff=4, mins=6)

