    FB("Inmiddels ben ik helemaal ___ aan het leven hier.", ["gewend"], "Revisão.", ["v-gewend-zijn"], choices=["gewend","wennen","gewoon"], tr="Entretanto estou completamente habituado à vida aqui."),
